import {CinematicFrame} from './dist/cinematic-frame.js?v=mobilefit01';
import {CinematicPresentation} from './dist/cinematic-presentation.js?v=directorcinematic02';
import {lightingProfile} from './dist/cinematic-direction-model.js?v=directorcinematic02';
import {imageKey} from './dist/cinematic-media.js?v=directorcinematic02';
const frame=new CinematicFrame(document.createElement('section'),{mount:document.body});frame.element.className='cinematic-frame cinematic-board-layer';
const presentation=new CinematicPresentation({status:s=>phases.push(s),controls:document.querySelector('#full')});
let item,assets,startCount=0,continuity;const phases=[];
function markers(){const c=document.createElement('canvas');c.width=1600;c.height=900;const x=c.getContext('2d');x.fillStyle='#302431';x.fillRect(0,0,1600,900);for(let i=0;i<8;i++){x.fillStyle=['#dc7c45','#d7c95a','#78ac83','#6b9fb6'][i%4];x.fillRect(i*200,0,200,900);x.fillStyle='#1a1921';x.font='bold 32px sans-serif';x.fillText(i===0?'EXT. ESQUERDA':i===7?'EXT. DIREITA':i<4?'ESQ. '+i:'DIR. '+i,i*200+6,450);}x.strokeStyle='white';x.lineWidth=12;x.strokeRect(6,6,1588,888);x.font='bold 32px sans-serif';x.fillText('TOPO / LUSTRE',650,55);x.fillText('BASE / MESA',650,870);x.fillStyle='#1c1924';x.fillRect(650,620,300,100);x.fillStyle='white';x.fillText('SOFÁ',750,680);return new Promise(r=>c.toBlob(r,'image/png'));}
async function setup(mode){
 await frame.clear({immediate:true});await presentation.end();continuity=null;assets={};let blob=mode==='reference'?await(await fetch('reference.png')).blob():await markers();const id=await imageKey(blob);assets[id]=blob;
 item={id:'fit-fixture',imageId:id,name:'Enquadramento distribuído',motion:'static',seconds:30,intensity:0,ending:'manual',fadeIn:0,fadeOut:0};
 if(mode!=='simple')item.layers=[]; // force real composition branch with a neutral camera
 if(mode!=='simple')item.camera={from:{x:.5,y:.5,zoom:1},to:{x:.5,y:.5,zoom:1},easing:'linear'};
 if(mode==='camera'){item.camera.to={x:.5,y:.5,zoom:1.2};item.layers=[{id:'layer',name:'Parallax',imageId:id,x:.5,y:.5,scale:.2,rotation:0,opacity:.5,parallax:.5,visible:true}];item.lighting=lightingProfile('theater');}
 if(mode==='video'){const video=await(await fetch('background.webm')).blob();const key=await imageKey(video);assets[key]=video;item.backgroundVideo={mediaId:key,enabled:true,loop:true,rate:1,delay:0,end:'fallback',transparent:false};const png=await(await fetch('alpha.png')).blob(),alpha=await(await fetch('alpha.webm')).blob(),pid=await imageKey(png),vid=await imageKey(alpha);assets[pid]=png;assets[vid]=alpha;item.layers=[{id:'alpha',name:'Camada transparente',imageId:pid,x:.5,y:.5,scale:.2,opacity:1,visible:true,parallax:.5,video:{mediaId:vid,enabled:true,loop:true,rate:1,delay:0,end:'fallback',transparent:true}}];}
 const abort=new AbortController();await presentation.begin({frame,signal:abort.signal});await frame.prepare(mode==='simple'?blob:assets,item);presentation.countdown(1800);await new Promise(r=>setTimeout(r,1800));await presentation.start(()=>{startCount++;return frame.startPrepared();});frame.pause();frame.seek(3);await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));return measure();
}
function rect(el){if(!el)return null;const r=el.getBoundingClientRect();return {width:r.width,height:r.height,x:r.x,y:r.y};}
function measure(){const el=frame.element,w=frame.composition?.world,img=el.querySelector('img'),logical={width:el.clientWidth,height:el.clientHeight},aspect=frame.composition?.aspect||img?.naturalWidth/img?.naturalHeight,world={width:w?parseFloat(w.style.width):Math.max(logical.width,logical.height*aspect),height:w?parseFloat(w.style.height):Math.max(logical.height,logical.width/aspect)};return {viewport:{width:innerWidth,height:innerHeight,visualWidth:visualViewport?.width,visualHeight:visualViewport?.height,scale:visualViewport?.scale,fullscreen:!!document.fullscreenElement},rotated:presentation.current?.root.getAttribute('data-landscape'),frameLogical:logical,frameVisual:rect(el),world,aspect,scale:world.width/(img?.naturalWidth||1600),visible:{width:Math.min(1,logical.width/world.width),height:Math.min(1,logical.height/world.height)},cropPercent:{x:100*Math.max(0,1-logical.width/world.width),y:100*Math.max(0,1-logical.height/world.height)},camera:frame.composition?.camera.style.transform||getComputedStyle(frame.composition?.camera||el).transform,time:frame.time(),generation:frame.generation,startCount,videos:[...el.querySelectorAll('video')].map(v=>({time:v.currentTime,ready:v.readyState,paused:v.paused,error:v.error?.code||null})),body:document.body.className,phases,continuity:continuity?{composition:continuity.composition===frame.composition,videos:continuity.videos.every((v,i)=>v===frame.composition?.videos[i])}:null};}
document.querySelector('#full').onclick=async()=>{await presentation.requestMode(presentation.current);document.dispatchEvent(new Event('resize'));};
window.addEventListener('message',async e=>{if(e.source!==parent||e.origin!==location.origin)return;try{let data;if(e.data.action==='load')data=await setup(e.data.mode);if(e.data.action==='measure'){await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));data=measure();}if(e.data.action==='play'){continuity={composition:frame.composition,videos:[...(frame.composition?.videos||[])]};frame.play();data=measure();}if(e.data.action==='stop'){await frame.clear({immediate:true});await presentation.end();data={stopped:!frame.item,body:document.body.className,roots:document.querySelectorAll('.cinematic-presentation').length};}parent.postMessage({fitReport:data,token:e.data.token},location.origin);}catch(error){parent.postMessage({fitReport:{error:error.message,stack:error.stack},token:e.data.token},location.origin);}});
